cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws);

// Summary stats
const totalOrders = data.length;
const confirmed = data.filter(r => r['Status'] === 'confirmed').length;
const cancelled = data.filter(r => r['Status'] === 'cancelled').length;
const totalRevenue = data.reduce((s, r) => s + r['Total Paid'], 0);
const confirmedRevenue = data.filter(r => r['Status'] === 'confirmed').reduce((s, r) => s + r['Total Paid'], 0);

// Unique customers
const customers = [...new Set(data.map(r => r['Customer']))];

// Top customers by spend
const custSpend = {};
data.forEach(r => { custSpend[r['Customer']] = (custSpend[r['Customer']] || 0) + r['Total Paid']; });
const topCust = Object.entries(custSpend).sort((a,b) => b[1]-a[1]).slice(0,5);

// Most popular items
const itemCount = {};
data.forEach(r => {
  r['Items'].split(', ').forEach(item => { itemCount[item] = (itemCount[item] || 0) + 1; });
});
const topItems = Object.entries(itemCount).sort((a,b) => b[1]-a[1]).slice(0,5);

// Date range
const dates = [...new Set(data.map(r => r['Date']))].sort();

console.log('--- ORDER SUMMARY ---');
console.log('Total Orders:', totalOrders);
console.log('Confirmed:', confirmed, '|  Cancelled:', cancelled);
console.log('Total Revenue (all orders):', '$' + totalRevenue);
console.log('Revenue (confirmed only):', '$' + confirmedRevenue);
console.log('Unique Customers:', customers.length);
console.log('Date Range:', dates[0], 'to', dates[dates.length-1]);
console.log();
console.log('--- TOP 5 CUSTOMERS BY SPEND ---');
topCust.forEach(([c,v]) => console.log(' ', c, ':', '$' + v));
console.log();
console.log('--- TOP 5 MOST ORDERED ITEMS ---');
topItems.forEach(([item, count]) => console.log(' ', item, ':', count, 'orders'));
"
